import{_ as t,o as a,c as r,a3 as o}from"./chunks/framework.CSV8cNZH.js";const h=JSON.parse('{"title":"Binance SDK production usage","description":"Handle Binance retries, uncertain order outcomes, stream recovery and shutdown.","frontmatter":{"title":"Binance SDK production usage","description":"Handle Binance retries, uncertain order outcomes, stream recovery and shutdown."},"headers":[],"relativePath":"guides/production.md","filePath":"guides/production.md"}'),n={name:"guides/production.md"};function i(s,e,c,d,l,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="production-usage" tabindex="-1">Production usage <a class="header-anchor" href="#production-usage" aria-label="Permalink to &quot;Production usage&quot;">​</a></h1><p>Use the <a href="/docs/binance/getting-started.html">Quickstart</a> to verify connectivity, then make request outcomes and connection state explicit in your application.</p><h2 id="set-timeouts-and-bound-concurrency" tabindex="-1">Set timeouts and bound concurrency <a class="header-anchor" href="#set-timeouts-and-bound-concurrency" aria-label="Permalink to &quot;Set timeouts and bound concurrency&quot;">​</a></h2><p>Choose an HTTP timeout appropriate to the operation and your application&#39;s latency budget. Set a maximum number of concurrent requests and avoid polling the same endpoint from many independent workers.</p><p><a href="/docs/binance/guides/configuration.html">Configure request options</a>.</p><h2 id="retry-reads-deliberately" tabindex="-1">Retry reads deliberately <a class="header-anchor" href="#retry-reads-deliberately" aria-label="Permalink to &quot;Retry reads deliberately&quot;">​</a></h2><p>Retry transient read failures with bounded exponential backoff and jitter. Respect rate-limit responses and server retry guidance. Stop after a defined number of attempts or deadline. Parameter, permission and signature failures need correction before another attempt.</p><h2 id="resolve-uncertain-order-outcomes" tabindex="-1">Resolve uncertain order outcomes <a class="header-anchor" href="#resolve-uncertain-order-outcomes" aria-label="Permalink to &quot;Resolve uncertain order outcomes&quot;">​</a></h2><p>A timeout can occur after an exchange has accepted an order. For Spot orders, track your <code>newClientOrderId</code>. After a timeout, query <code>getOrder()</code> using the symbol and <code>origClientOrderId</code> or <code>orderId</code>, then reconcile fills if needed. Use the matching futures client&#39;s query methods for derivatives. Do not treat every order endpoint as safe to repeat.</p><p>Persist the identifiers needed for reconciliation before submitting an order. Distinguish a transport acknowledgement, an accepted order and a fill in your application state.</p><h2 id="recover-streaming-state" tabindex="-1">Recover streaming state <a class="header-anchor" href="#recover-streaming-state" aria-label="Permalink to &quot;Recover streaming state&quot;">​</a></h2><p>Listen for <code>reconnecting</code>, <code>reconnected</code> and <code>exception</code>. The client manages reconnection and remembered subscriptions. Application state can still be stale after a connection gap; reconcile orders and balances before acting on cached values.</p><p>For a local order book, follow Binance&#39;s documented snapshot and depth-update sequence rules. Reconnecting a socket alone does not rebuild an accurate book.</p><p>Record the last update time and mark stale feeds explicitly. Avoid placing new orders based solely on a reconnected event.</p><h2 id="observe-failures-without-exposing-credentials" tabindex="-1">Observe failures without exposing credentials <a class="header-anchor" href="#observe-failures-without-exposing-credentials" aria-label="Permalink to &quot;Observe failures without exposing credentials&quot;">​</a></h2><p>Record operation names, response codes, request duration, retry counts and reconnect events. Log selected fields rather than complete request or error objects. See <a href="/docs/binance/guides/errors.html">Error handling</a> for this SDK&#39;s response shapes.</p><h2 id="shut-down-cleanly" tabindex="-1">Shut down cleanly <a class="header-anchor" href="#shut-down-cleanly" aria-label="Permalink to &quot;Shut down cleanly&quot;">​</a></h2><p>Stop accepting new work, settle or reconcile outstanding requests, call <code>WebsocketClient.closeAll()</code>, and clear application timers. The <a href="/docs/binance/guides/websockets.html">stream example</a> shows signal handlers and a bounded run.</p><h2 id="keep-the-sdk-up-to-date" tabindex="-1">Keep the SDK up to date <a class="header-anchor" href="#keep-the-sdk-up-to-date" aria-label="Permalink to &quot;Keep the SDK up to date&quot;">​</a></h2><p>Use the latest SDK release. Review release notes and run your application&#39;s integration checks before deploying an upgrade. Commit your lockfile for reproducible deployments.</p><p><a href="https://github.com/sieblyio/binance/releases" target="_blank" rel="noreferrer">Repository releases</a> · <a href="https://developers.binance.com/docs/binance-spot-api-docs" target="_blank" rel="noreferrer">Current exchange documentation</a></p>',21)])])}const m=t(n,[["render",i]]);export{h as __pageData,m as default};
